import json
import unittest
from unittest.mock import patch

import selector_shadow


# Exact leading bytes returned by eth_getCode for the Optimism WETH predeploy
# at 0x4200000000000000000000000000000000000006. The dispatcher constants are
# chain-observed values, not signatures generated by this test.
OPTIMISM_WETH_HEAD = (
    "0x6080604052600436106100bc5760003560e01c8063313ce56711610074578063"
    "a9059cbb1161004e578063a9059cbb146102cb578063d0e30db0146100bc578063"
    "dd62ed3e14610311576100bc565b8063313ce5671461024b57806370a082311461"
    "027657806395d89b41146102b6576100bc565b806318160ddd116100a557806318"
    "160ddd146101aa57806323b872dd146101d15780632e1a7d4d14610221576100bc"
    "565b806306fdde03146100c6578063095ea7b314610150575b"
)


# Optimism mainnet block zero, kept as a fixed JSON-RPC fixture.
OPTIMISM_GENESIS_RESPONSE = {
    "jsonrpc": "2.0",
    "id": 1,
    "result": {
        "number": "0x0",
        "hash": "0x7ca38a1916c42007829c55e69d3e9a73265554b586a499015373241b8a3fa48b",
    },
}


class _FakeResponse:
    def __init__(self, body):
        self.body = body

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        return False

    def read(self):
        return self.body


class SelectorShadowTests(unittest.TestCase):
    def test_real_chain_dispatcher_constants_are_found(self):
        result = selector_shadow.analyze_bytecode(OPTIMISM_WETH_HEAD)
        self.assertIn("0xa9059cbb", result["selectors"])
        self.assertIn("0x70a08231", result["selectors"])
        self.assertIn("0x06fdde03", result["selectors"])
        self.assertEqual(result["selector_offsets"]["0xa9059cbb"], [42])

    def test_collision_is_the_set_intersection(self):
        proxy = "0x60003560e01c63a9059cbb14610010576312345678146100105700"
        implementation = "0x60003560e01c63a9059cbb146100105763deadbeef146100105700"
        result = selector_shadow.compare_bytecode(proxy, implementation)
        self.assertEqual(result["collisions"], ["0xa9059cbb"])
        self.assertEqual(result["verdict"], "collision-found")

    def test_push_data_without_eq_is_not_a_selector(self):
        result = selector_shadow.analyze_bytecode("0x63a9059cbb6000")
        self.assertEqual(result["selectors"], [])

    def test_solidity_metadata_is_not_scanned(self):
        executable = bytes.fromhex("60003560e01c63a9059cbb146100105700")
        metadata = bytes.fromhex("a164736f6c634300080f")
        code = "0x" + (executable + metadata + len(metadata).to_bytes(2, "big")).hex()
        result = selector_shadow.analyze_bytecode(code)
        self.assertEqual(result["executable_bytes"], len(executable))
        self.assertEqual(result["selectors"], ["0xa9059cbb"])

    def test_fixed_chain_block_fixture_is_preserved(self):
        self.assertEqual(
            OPTIMISM_GENESIS_RESPONSE["result"]["hash"],
            "0x7ca38a1916c42007829c55e69d3e9a73265554b586a499015373241b8a3fa48b",
        )

    def test_rpc_request_is_replaceable_in_tests(self):
        body = json.dumps({"jsonrpc": "2.0", "id": 1, "result": "0x6000"}).encode()
        with patch("selector_shadow.urllib.request.urlopen", return_value=_FakeResponse(body)) as call:
            self.assertEqual(
                selector_shadow.rpc_call("http://rpc.invalid", "eth_getCode", ["0xabc", "latest"]),
                "0x6000",
            )
        self.assertEqual(call.call_count, 1)


if __name__ == "__main__":
    unittest.main()
